            <div className="hb-kb2-ticks" aria-hidden="true">
              {Array.from({ length: 30 }, (_, j) => (
                <i key={j} data-warn={j === 17 ? "true" : undefined} style={{ "--hb-kb2-j": j } as React.CSSProperties} />
